ROOT = Path(__file__).resolve().parent

def default_content(relative: str) -> str:
    name = Path(relative).name
    suffix = Path(relative).suffix.lower()

    if suffix == ".py":
        if name == "__init__.py":
            return '"""AURA API package module."""\n'
        return (
            f'"""AURA API module: {relative}.\n\n'
            'Architecture scaffold only. Implement real domain behavior; '
            'do not add placeholder validate/execute/health shells.\n"""\n'
        )
    if name == "README.md":
        return "# AURA API\n\nProduction-oriented intelligence gateway for the AURA ecosystem.\n"
    if suffix == ".md":
        return f"# {Path(relative).stem.replace('_', ' ').title()}\n\nDocumentation for AURA API.\n"
    if suffix in {".yml", ".yaml"}:
        return "# AURA API deployment/configuration artifact\n"
    if suffix == ".toml":
        return '[build-system]\nrequires = ["hatchling"]\nbuild-backend = "hatchling.build"\n'
    if name == ".env.example":
        return "AURA_API_ENVIRONMENT=development\nAURA_API_HOST=127.0.0.1\nAURA_API_PORT=8000\n"
    if name == ".gitignore":
        return ".venv/\n__pycache__/\n.pytest_cache/\n.mypy_cache/\n.ruff_cache/\n.env\n"
    return ""

def main() -> None:
    created_dirs = 0
    created_files = 0
    skipped_files = 0

    for directory in MANIFEST["dirs"]:
        path = ROOT / directory
        if not path.exists():
            path.mkdir(parents=True, exist_ok=True)
            created_dirs += 1

    for relative in MANIFEST["files"]:
        path = ROOT / relative
        path.parent.mkdir(parents=True, exist_ok=True)
        if path.exists():
            skipped_files += 1
            continue
        path.write_text(default_content(relative), encoding="utf-8")
        created_files += 1

    print("\nAURA API repository generation complete!")
    print(f"Root: {ROOT}")
    print(f"Directories created: {created_dirs}")
    print(f"Files created: {created_files}")
    print(f"Existing files preserved: {skipped_files}")
    print(f"Total planned directories: {len(MANIFEST['dirs'])}")
    print(f"Total planned files: {len(MANIFEST['files'])}")
    print("\nIMPORTANT: This generator creates the architecture only.")
    print("Implementation must add real, tested domain behavior without generic placeholder code.")

if __name__ == "__main__":
    main()
